import pyotp
import pytest

import app.auth as auth
from app.auth import AuthError, get_session, login
from app.config import USERS


def _otp(username: str) -> str:
    return pyotp.TOTP(USERS[username]["otp_secret"]).now()


def test_login_correcto_abre_sesion():
    s = login("alice", "alice-pass", _otp("alice"))
    assert s.username == "alice"
    assert get_session(s.token) == s


def test_login_incorrecto():
    with pytest.raises(AuthError):
        login("alice", "mal", _otp("alice"))
    with pytest.raises(AuthError):
        login("nadie", "alice-pass", _otp("alice"))


def test_login_otp_invalido_o_vacio():
    with pytest.raises(AuthError):
        login("alice", "alice-pass", "000000")
    with pytest.raises(AuthError):
        login("alice", "alice-pass", "")


def test_login_sin_otp_falla():
    with pytest.raises(TypeError):
        login("alice", "alice-pass")


def test_login_usa_verificar_otp_del_modulo(monkeypatch):
    monkeypatch.setattr(auth, "verificar_otp", lambda username, code: True)
    s = login("alice", "alice-pass", "cualquier-cosa")
    assert s.username == "alice"


def test_endpoint_login(client):
    otp = _otp("bob")
    assert client.post(
        "/login", json={"username": "bob", "password": "bob-pass", "otp": otp}
    ).status_code == 200
    assert client.post(
        "/login", json={"username": "bob", "password": "x", "otp": otp}
    ).status_code == 401


def test_endpoint_login_sin_otp_o_invalido(client):
    assert client.post(
        "/login", json={"username": "bob", "password": "bob-pass"}
    ).status_code == 401
    assert client.post(
        "/login", json={"username": "bob", "password": "bob-pass", "otp": "000000"}
    ).status_code == 401


def test_otp_header_lee_cabecera():
    from fastapi import Depends, FastAPI
    from fastapi.testclient import TestClient

    app_ = FastAPI()

    @app_.get("/necesita-otp")
    def _endpoint(otp: str = Depends(auth.otp_header)):
        return {"otp": otp}

    client = TestClient(app_)
    assert client.get("/necesita-otp", headers={"X-OTP": "123456"}).json() == {"otp": "123456"}
    assert client.get("/necesita-otp").json() == {"otp": ""}
    assert "X-OTP" in auth.otp_header.__doc__

